// Structure for tokens
typedef struct {
    int type; // 0: number, 1: operator, 2: '(' , 3: ')'
    int value; // number value if type==0, operator char if type==1
} Token;

// Parse expression into tokens
int parse(char *expr, Token *tokens) {
    int len = strlen(expr);
    int pos = 0;
    int tpos = 0;
    while (pos < len) {
        if (isspace(expr[pos])) {
            pos++;
            continue;
        }
        if (isdigit(expr[pos])) {
            int num = 0;
            while (pos < len && isdigit(expr[pos])) {
                num = num * 10 + (expr[pos] - '0');
                pos++;
            }
            tokens[tpos].type = 0;
            tokens[tpos].value = num;
            tpos++;
        } else if (expr[pos] == '+' || expr[pos] == '-' || expr[pos] == '*') {
            tokens[tpos].type = 1;
            tokens[tpos].value = expr[pos];
            tpos++;
            pos++;
        } else if (expr[pos] == '(') {
            tokens[tpos].type = 2;
            tokens[tpos].value = '(';
            tpos++;
            pos++;
        } else if (expr[pos] == ')') {
            tokens[tpos].type = 3;
            tokens[tpos].value = ')';
            tpos++;
            pos++;
        } else {
            pos++;
        }
    }
    return tpos;
}

// Evaluate expression given precedence: 0=lowest, 1=middle, 2=highest
// op1, op2, op3 are the operators with precedence 0,1,2 respectively
// Returns the value
int evaluate(Token *tokens, int n, int prec[3]) {
    // We'll use recursive descent with precedence climbing
    // First convert tokens to a flat list for easier handling
    // We'll implement a simple evaluator that respects given precedence

    // Stack-based shunting yard evaluation
    int val_stack[100];
    char op_stack[100];
    int val_top = -1, op_top = -1;

    int i = 0;
    while (i < n) {
        if (tokens[i].type == 0) {
            val_stack[++val_top] = tokens[i].value;
            i++;
        } else if (tokens[i].type == 2) { // '('
            op_stack[++op_top] = '(';
            i++;
        } else if (tokens[i].type == 3) { // ')'
            while (op_top >= 0 && op_stack[op_top] != '(') {
                char op = op_stack[op_top--];
                int b = val_stack[val_top--];
                int a = val_stack[val_top--];
                int res;
                if (op == '+') res = a + b;
                else if (op == '-') res = a - b;
                else res = a * b;
                val_stack[++val_top] = res;
            }
            if (op_top >= 0) op_top--; // pop '('
            i++;
        } else { // operator
            char op = tokens[i].value;
            int cur_prec;
            if (op == '+') cur_prec = prec[0];
            else if (op == '-') cur_prec = prec[1];
            else cur_prec = prec[2];

            while (op_top >= 0 && op_stack[op_top] != '(') {
                char top_op = op_stack[op_top];
                int top_prec;
                if (top_op == '+') top_prec = prec[0];
                else if (top_op == '-') top_prec = prec[1];
                else top_prec = prec[2];

                // Left associative: while top has >= precedence
                if (top_prec >= cur_prec) {
                    op_top--;
                    int b = val_stack[val_top--];
                    int a = val_stack[val_top--];
                    int res;
                    if (top_op == '+') res = a + b;
                    else if (top_op == '-') res = a - b;
                    else res = a * b;
                    val_stack[++val_top] = res;
                } else {
                    break;
                }
            }
            op_stack[++op_top] = op;
            i++;
        }
    }

    while (op_top >= 0) {
        char op = op_stack[op_top--];
        int b = val_stack[val_top--];
        int a = val_stack[val_top--];
        int res;
        if (op == '+') res = a + b;
        else if (op == '-') res = a - b;
        else res = a * b;
        val_stack[++val_top] = res;
    }

    return val_stack[0];
}

