ll apply_op(char op, ll a, ll b) {
    if (op == '+') return a + b;
    if (op == '-') return a - b;
    return a * b;
}

/*
We assign each operator a rank 0..2.
Smaller rank = lower precedence.
Equal rank => same precedence, evaluated left-associatively.

For a flat expression v0 op0 v1 op1 v2 ...,
with fixed child values, evaluate by repeatedly collapsing operators
from lower precedence to higher precedence; inside same precedence,
left to right.
*/
ll eval_flat(ll vals[], char ops[], int m, int rankmap[256]) {
    ll curVals[MAXN];
    char curOps[MAXN];

    int vn = m + 1;
    for (int i = 0; i < vn; i++) curVals[i] = vals[i];
    for (int i = 0; i < m; i++) curOps[i] = ops[i];

    for (int lev = 0; lev < 3; lev++) {
        ll newVals[MAXN];
        char newOps[MAXN];
        int nv = 0, no = 0;

        newVals[nv++] = curVals[0];
        for (int i = 0; i < m; i++) {
            if (rankmap[(unsigned char)curOps[i]] == lev) {
                newVals[nv - 1] = apply_op(curOps[i], newVals[nv - 1], curVals[i + 1]);
            } else {
                newOps[no++] = curOps[i];
                newVals[nv++] = curVals[i + 1];
            }
        }

        m = no;
        for (int i = 0; i < nv; i++) curVals[i] = newVals[i];
        for (int i = 0; i < no; i++) curOps[i] = newOps[i];
    }

    return curVals[0];
}

ll solve(Node *node, int rankmap[256]) {
    if (node->is_num) return node->num;

    ll vals[MAXN];
    for (int i = 0; i < node->cnt; i++) {
        vals[i] = solve(node->child[i], rankmap);
    }
    return eval_flat(vals, node->ops, node->cnt - 1, rankmap);
}

