        tokens.push_back(num);
    }

    // We'll evaluate using a stack-based approach that respects precedence
    // First, handle parentheses by recursively evaluating subexpressions
    // We'll convert to RPN using shunting-yard algorithm with custom precedence

    stack<char> ops;
    vector<string> output;

    for (const string& token : tokens) {
        if (isdigit(token[0])) {
            output.push_back(token);
        } else if (token == "(") {
            ops.push('(');
        } else if (token == ")") {
            while (!ops.empty() && ops.top() != '(') {
                output.push_back(string(1, ops.top()));
                ops.pop();
            }
            if (!ops.empty()) ops.pop(); // remove '('
        } else { // operator
            char op = token[0];
            while (!ops.empty() && ops.top() != '(' && 
                   precMap[ops.top()] <= precMap[op]) {
                output.push_back(string(1, ops.top()));
                ops.pop();
            }
            ops.push(op);
        }
    }

    while (!ops.empty()) {
        output.push_back(string(1, ops.top()));
        ops.pop();
    }

    // Evaluate RPN
    stack<long long> st;
    for (const string& token : output) {
        if (isdigit(token[0])) {
            st.push(stoll(token));
        } else {
            long long b = st.top(); st.pop();
            long long a = st.top(); st.pop();
            if (token == "+") st.push(a + b);
            else if (token == "-") st.push(a - b);
            else if (token == "*") st.push(a * b);
        }
    }

    return st.top();
}

