using int64 = long long;

struct Node {
    char op;                 // 0 for number, otherwise '+', '-', '*'
    int64 val;               // valid if op == 0
    vector<Node*> ch;        // children after parsing with chosen precedence
    Node(char op_=0, int64 v=0) : op(op_), val(v) {}
};

string s;
int posi = 0;
array<int, 256> precv;

// Parse expression under current precedence setting.
// Grammar is handled by precedence climbing with left associativity.
Node* parse_expr(int min_prec);

Node* parse_primary() {
    if (s[posi] == '(') {
        ++posi; // '('
        Node* inside = parse_expr(0);
        ++posi; // ')'
        return inside;
    } else {
        int64 x = 0;
        while (posi < (int)s.size() && isdigit((unsigned char)s[posi])) {
            x = x * 10 + (s[posi] - '0');
            ++posi;
        }
        return new Node(0, x);
    }
}

Node* parse_expr(int min_prec) {
    Node* left = parse_primary();
    while (posi < (int)s.size()) {
        char op = s[posi];
        if (op != '+' && op != '-' && op != '*') break;
        int p = precv[(unsigned char)op];
        if (p < min_prec) break;

        ++posi; // consume operator
        Node* right = parse_expr(p + 1); // left associative

        if (left->op == op) {
            left->ch.push_back(right);
        } else {
            Node* now = new Node(op);
            now->ch.push_back(left);
            now->ch.push_back(right);
            left = now;
        }
    }
    return left;
}

// For each parsed tree, compute [min, max] obtainable by assigning
// precedence recursively inside parentheses already fixed by parsing.
// Since parsed tree already reflects precedence, only need ordinary eval,
// but for '-' we need both min/max of children to combine safely.
pair<int64,int64> solve(Node* u) {
    if (u->op == 0) return {u->val, u->val};

    vector<pair<int64,int64>> vals;
    for (auto v : u->ch) vals.push_back(solve(v));

    if (u->op == '+') {
        int64 mn = 0, mx = 0;
        for (auto [a,b] : vals) {
            mn += a;
            mx += b;
        }
        return {mn, mx};
    } else if (u->op == '*') {
        // Inputs are nonnegative? Not guaranteed by intermediate results.
        // Need exact min/max over sequential multiplication of intervals.
        int64 mn = 1, mx = 1;
        bool first = true;
        for (auto [a,b] : vals) {
            if (first) {
                mn = a; mx = b; first = false;
            } else {
                int64 c1 = mn * a, c2 = mn * b, c3 = mx * a, c4 = mx * b;
                mn = min(min(c1, c2), min(c3, c4));
                mx = max(max(c1, c2), max(c3, c4));
            }
        }
        return {mn, mx};
    } else { // '-'
        // left associative flattening: a - b - c - ...
        int64 mn = vals[0].first;
        int64 mx = vals[0].second;
        for (int i = 1; i < (int)vals.size(); ++i) {
            int64 a = vals[i].first, b = vals[i].second;
            int64 nmn = mn - b;
            int64 nmx = mx - a;
            mn = nmn;
            mx = nmx;
        }
        return {mn, mx};
    }
}

void cleanup(Node* u) {
    for (auto v : u->ch) cleanup(v);
    delete u;
}

