def evaluate(tokens, prec):
    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def consume():
        t = tokens[pos[0]]
        pos[0] += 1
        return t

    def parse_expr(min_prec):
        left = parse_primary()
        while True:
            op = peek()
            if op not in prec:
                break
            p = prec[op]
            if p < min_prec:
                break
