# Parse expression into an AST:
# node = ('num', value) or ('op', operator, left, right)
def parse_expression(text):
    n = len(text)
    i = 0

    def parse_factor():
        nonlocal i
        if text[i] == '(':
            i += 1
            node = parse_expr()
            i += 1  # skip ')'
            return node
        else:
            j = i
            while i < n and text[i].isdigit():
                i += 1
            return ('num', int(text[j:i]))

    def parse_expr():
        nonlocal i
        node = parse_factor()
        while i < n and text[i] != ')':
            op = text[i]
            i += 1
            right = parse_factor()
            node = ('op', op, node, right)
        return node

    return parse_expr()


