# Enumerate all total preorders (allow ties) on 3 operators.
# We represent precedence by integer rank; larger rank = higher precedence.
# All mappings from ops to {0,1,2} are considered, then normalized by order of used ranks.
def all_precedences():
    res = []
    seen = set()
    for a in range(3):
        for b in range(3):
            for c in range(3):
                ranks = {'+': a, '-': b, '*': c}
                used = sorted(set(ranks.values()))
                mp = {v: idx for idx, v in enumerate(used)}
                norm = tuple(mp[ranks[ch]] for ch in ops)
                if norm not in seen:
                    seen.add(norm)
                    res.append({ops[i]: norm[i] for i in range(3)})
    return res


precedences = all_precedences()


def apply(op, x, y):
    if op == '+':
        return x + y
    if op == '-':
        return x - y
    return x * y


# For a fixed precedence, evaluate an AST where every non-parenthesized subexpression
# is originally left-associative. Parentheses are already encoded in the AST.
# We first flatten each AST node into values/operators at that parenthesis level,
# then reduce by precedence levels, keeping left associativity within the same level.
def eval_with_prec(node, prec):
    @lru_cache(None)
    def solve(nd):
        kind = nd[0]
        if kind == 'num':
            return nd[1]

        vals = []
        oprs = []

        def collect(cur):
            if cur[0] == 'op':
                collect(cur[2])
                oprs.append(cur[1])
                vals.append(solve(cur[3]))
            else:
                vals.append(cur[1])

        collect(nd)

        max_rank = max(prec.values())
        cur_vals = vals
        cur_ops = oprs

        for rank in range(max_rank, -1, -1):
            if not cur_ops:
                break
            new_vals = [cur_vals[0]]
            new_ops = []
            for i, op in enumerate(cur_ops):
                v = cur_vals[i + 1]
                if prec[op] == rank:
                    new_vals[-1] = apply(op, new_vals[-1], v)
                else:
                    new_ops.append(op)
                    new_vals.append(v)
            cur_vals, cur_ops = new_vals, new_ops

        return cur_vals[0]

    return solve(node)


