public class Main {

    // Evaluate expression with given precedence order (higher index = higher precedence)
    // Precedence array: index 0 for '+', 1 for '-', 2 for '*'
    static long evaluate(String expr, int[] prec) {
        // First, handle parentheses recursively
        StringBuilder sb = new StringBuilder();
        int i = 0;
        while (i < expr.length()) {
            char c = expr.charAt(i);
            if (c == '(') {
                int depth = 1;
                int j = i + 1;
                while (j < expr.length() && depth > 0) {
                    if (expr.charAt(j) == '(') depth++;
                    else if (expr.charAt(j) == ')') depth--;
                    j++;
                }
                // Evaluate inside parentheses with same precedence
                long inner = evaluate(expr.substring(i + 1, j - 1), prec);
                sb.append(inner);
                i = j;
            } else {
                sb.append(c);
                i++;
            }
        }

        // Now we have expression without parentheses, tokenize
        String s = sb.toString();
        List<String> tokens = new ArrayList<>();
        StringBuilder num = new StringBuilder();
        for (int k = 0; k < s.length(); k++) {
            char c = s.charAt(k);
            if (Character.isDigit(c) || (c == '-' && (k == 0 || s.charAt(k-1) == '+' || s.charAt(k-1) == '-' || s.charAt(k-1) == '*'))) {
                // Handle negative numbers at start or after operator
                if (c == '-' && (k == 0 || "+-*".indexOf(s.charAt(k-1)) != -1)) {
                    num.append(c);
                } else if (Character.isDigit(c)) {
                    num.append(c);
                } else {
                    if (num.length() > 0) {
                        tokens.add(num.toString());
                        num = new StringBuilder();
                    }
                    tokens.add(String.valueOf(c));
                }
            } else {
                if (num.length() > 0) {
                    tokens.add(num.toString());
                    num = new StringBuilder();
                }
                tokens.add(String.valueOf(c));
            }
        }
        if (num.length() > 0) {
            tokens.add(num.toString());
        }

        // Evaluate based on precedence
        // We'll do multiple passes: for each precedence level from lowest to highest
        List<String> list = new ArrayList<>(tokens);
        int maxPrec = Math.max(prec[0], Math.max(prec[1], prec[2]));

        for (int p = 0; p <= maxPrec; p++) {
            List<String> newList = new ArrayList<>();
            int idx = 0;
            while (idx < list.size()) {
                String token = list.get(idx);
                if (token.equals("+") || token.equals("-") || token.equals("*")) {
                    int opPrec = 0;
                    if (token.equals("+")) opPrec = prec[0];
                    else if (token.equals("-")) opPrec = prec[1];
                    else opPrec = prec[2];

                    if (opPrec == p) {
                        // Evaluate this operator with left and right operands
                        long left = Long.parseLong(newList.remove(newList.size() - 1));
                        long right = Long.parseLong(list.get(idx + 1));
                        long result;
                        if (token.equals("+")) result = left + right;
                        else if (token.equals("-")) result = left - right;
                        else result = left * right;
                        newList.add(String.valueOf(result));
                        idx += 2; // skip operator and right operand
                    } else {
                        newList.add(token);
                        idx++;
                    }
                } else {
                    newList.add(token);
                    idx++;
                }
            }
            list = newList;
        }

        return Long.parseLong(list.get(0));
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String expr = br.readLine().trim();

        long maxVal = Long.MIN_VALUE;

        // Generate all 27 precedence assignments (3 operators, 3 precedence levels 0,1,2)
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                for (int k = 0; k < 3; k++) {
                    int[] prec = {i, j, k}; // +, -, *
                    long val = evaluate(expr, prec);
                    if (val > maxVal) maxVal = val;
                }
            }
        }

        System.out.println(maxVal);
    }
}

