import java.io.*;
import java.util.*;

public class Main {
    // AST node
    static abstract class Node {
        abstract long eval(int[] prec);
    }

    static class NumNode extends Node {
        long val;
        NumNode(long v) { this.val = v; }
        long eval(int[] prec) { return val; }
    }

    static class OpNode extends Node {
        char op;
        Node left, right;
        OpNode(char op, Node left, Node right) {
            this.op = op;
            this.left = left;
            this.right = right;
        }
        long eval(int[] prec) {
            long a = left.eval(prec);
            long b = right.eval(prec);
            if (op == '+') return a + b;
            if (op == '-') return a - b;
            return a * b;
        }
    }

    static class Parser {
        String s;
        int n, pos;

        Parser(String s) {
            this.s = s;
            this.n = s.length();
            this.pos = 0;
        }

        Node parse() {
            return expr();
        }

        Node expr() {
            Node cur = factor();
            while (pos < n && isOp(s.charAt(pos))) {
                char op = s.charAt(pos++);
                Node rhs = factor();
                cur = new OpNode(op, cur, rhs);
            }
            return cur;
        }

        Node factor() {
            char c = s.charAt(pos);
            if (c == '(') {
                pos++;
                Node inside = expr();
                pos++; // ')'
                return inside;
            } else {
                long v = 0;
                while (pos < n && Character.isDigit(s.charAt(pos))) {
                    v = v * 10 + (s.charAt(pos) - '0');
                    pos++;
                }
                return new NumNode(v);
            }
        }

        boolean isOp(char c) {
            return c == '+' || c == '-' || c == '*';
        }
    }

    static int idx(char op) {
        if (op == '+') return 0;
        if (op == '-') return 1;
        return 2;
    }

    // Rebuild tree according to precedence, preserving left associativity for equal precedence
    static Node rebuild(Node root, int[] prec) {
        if (root instanceof NumNode) return root;
        List<Node> vals = new ArrayList<>();
        List<Character> ops = new ArrayList<>();
        flatten(root, vals, ops, prec);

        List<Node> v2 = new ArrayList<>(vals);
        List<Character> o2 = new ArrayList<>(ops);

        // Higher numeric value means higher precedence
        for (int p = 2; p >= 0; p--) {
            List<Node> nv = new ArrayList<>();
            List<Character> no = new ArrayList<>();
            Node cur = v2.get(0);
            for (int i = 0; i < o2.size(); i++) {
                char op = o2.get(i);
                Node nxt = v2.get(i + 1);
                if (prec[idx(op)] == p) {
                    cur = new OpNode(op, cur, nxt); // left associative
                } else {
                    nv.add(cur);
                    no.add(op);
                    cur = nxt;
                }
            }
            nv.add(cur);
            v2 = nv;
            o2 = no;
        }
        return v2.get(0);
    }

    // Flatten only chains at this parenthesis level.
    static void flatten(Node node, List<Node> vals, List<Character> ops, int[] prec) {
        if (node instanceof NumNode) {
            vals.add(node);
            return;
        }
        OpNode opn = (OpNode) node;
        Node left = rebuild(opn.left, prec);
        Node right = rebuild(opn.right, prec);

        vals.add(left);
        ops.add(opn.op);
        vals.add(right);
    }

    static long solve(Node root) {
        long ans = Long.MIN_VALUE;
        // precedence values 0..2, equal allowed
        for (int pAdd = 0; pAdd <= 2; pAdd++) {
            for (int pSub = 0; pSub <= 2; pSub++) {
                for (int pMul = 0; pMul <= 2; pMul++) {
                    int[] prec = new int[3];
                    prec[0] = pAdd;
                    prec[1] = pSub;
                    prec[2] = pMul;
                    Node rebuilt = rebuildAll(root, prec);
                    long val = rebuilt.eval(prec);
                    if (val > ans) ans = val;
                }
            }
        }
        return ans;
    }

    // Proper recursive rebuilding:
    // first recursively rebuild children inside parentheses/subexpressions,
    // then flatten current node's chain and rebuild by precedence.
    static Node rebuildAll(Node node, int[] prec) {
        if (node instanceof NumNode) return node;

        List<Node> vals = new ArrayList<>();
        List<Character> ops = new ArrayList<>();
        collectChain(node, vals, ops, prec);

        List<Node> v = new ArrayList<>(vals);
        List<Character> o = new ArrayList<>(ops);

        for (int p = 2; p >= 0; p--) {
            List<Node> nv = new ArrayList<>();
            List<Character> no = new ArrayList<>();
            Node cur = v.get(0);
            for (int i = 0; i < o.size(); i++) {
                char op = o.get(i);
                Node nxt = v.get(i + 1);
                if (prec[idx(op)] == p) {
                    cur = new OpNode(op, cur, nxt);
                } else {
                    nv.add(cur);
                    no.add(op);
                    cur = nxt;
                }
            }
            nv.add(cur);
            v = nv;
            o = no;
        }
        return v.get(0);
    }

    // Collects a maximal chain from the original left-associative parse at the same parenthesis level.
    static void collectChain(Node node, List<Node> vals, List<Character> ops, int[] prec) {
        if (!(node instanceof OpNode)) {
            vals.add(rebuildAll(node, prec));
            return;
        }
        OpNode opn = (OpNode) node;

        // Since original parse is fully left-associative within same parenthesis level,
        // the left child may continue the same chain, but the right child is a factor/subexpression.
        if (opn.left instanceof OpNode) {
            collectChain(opn.left, vals, ops, prec);
        } else {
            vals.add(rebuildAll(opn.left, prec));
        }
        ops.add(opn.op);
        vals.add(rebuildAll(opn.right, prec));
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        Parser parser = new Parser(s);
        Node root = parser.parse();
        System.out.println(solve(root));
    }
}
